Чтобы написать скрипт контроллера от первого лица в GDScript и применить его к узлу KinematicBody в Godot Engine 3.x, выполните следующие шаги:

1. Создайте новый проект в Godot Engine 3.x и выберите шаблон "2D" или "3D", в зависимости от ваших нужд.
2. Создайте новый объект KinematicBody в вашей сцене или в предназначенном для этого объекте.
3. Создайте новый скрипт (File > New > Script) и назовите его "player_controller.gd".
4. В скрипте "player_controller.gd", напишите следующий код:

```
extends KinematicBody2D if 2D project
extends KinematicBody if 3D project

export var speed := 200.0
export var mouse_sensitivity := 0.2

var velocity := Vector2.ZERO
var camera_rot := Vector2.ZERO

func _ready():
    if is_3d_scene():
        make_current_camera_3d()
    else:
        make_current_camera_2d()

func _unhandled_input(event):
    if event.is_action_pressed("move_forward"):
        velocity.y -= 1
    if event.is_action_pressed("move_backward"):
        velocity.y += 1
    if event.is_action_pressed("move_left"):
        velocity.x -= 1
    if event.is_action_pressed("move_right"):
        velocity.x += 1

    if event.is_action_pressed("look_up"):
        camera_rot.y -= mouse_sensitivity
    if event.is_action_pressed("look_down"):
        camera_rot.y += mouse_sensitivity

func _input(event):
    if event is InputEventMouseMotion and not event.is_echo():
        camera_rot.x -= event.relative.y * mouse_sensitivity
        camera_rot.x = clamp(camera_rot.x, -90, 90)

func _physics_process(delta):
    if is_3d_scene():
        velocity = move_and_slide(velocity, Vector3.UP)
        rotation.y = camera_rot.x * deg2rad(1)
    else:
        velocity = move_and_slide(velocity, Vector2.UP)
        rotation = Vector2(camera_rot.x, 0)

func is_3d_scene() -> bool:
    return extends("KinematicBody") and not extends("KinematicBody2D")

func make_current_camera_2d():
    var main_camera = get_node_or_null("MainCamera")
    if main_camera:
        main_camera.make_current()

func make_current_camera_3d():
    var main_camera = get_node_or_null("MainCamera3D")
    if main_camera:
        main_camera.make_current()
```

5. В редакторе сцены, добавьте новый сценарий к объекту KinematicBody, выбрав "player_controller.gd" в качестве скрипта.

6. В редакторе сцены, добавьте контроллеры движения (например, WASD или стрелки на клавиатуре) и камерный поворот (например, поворот мыши в 3D, или вертикальный и горизонтальный поворот мыши в 2D) в настройках проекта.

7. Запустите игру и проверьте, что ваша камера и объект KinematicBody двигаются и поворачиваются в соответствии с вашими настройками.

